import{_ as a,o as n,c as t,a3 as p}from"./chunks/framework.Dz5Q8p4s.js";const g=JSON.parse('{"title":"Can Video Large Multimodal Models Think Like Doubters-or Double-Down: A Study on Defeasible Video Entailment","description":"","frontmatter":{"title":"Can Video Large Multimodal Models Think Like Doubters-or Double-Down: A Study on Defeasible Video Entailment","arxiv":"2506.22385","date":"2025-06-27","authors":"Yue Zhang, Jilei Sun, Yunhui Guo, Vibhav Gogate","categories":"cs.AI, cs.CL, cs.CV","topics":"视频推理, 可废止推理, 基准构建","outline":[2,2]},"headers":[],"relativePath":"papers/2506.22385.md","filePath":"papers/2506.22385.md","lastUpdated":null}'),e={name:"papers/2506.22385.md"};function l(r,s,m,i,c,h){return n(),t("div",null,[...s[0]||(s[0]=[p('<h1 id="can-video-large-multimodal-models-think-like-doubters-or-double-down-a-study-on-defeasible-video-entailment" tabindex="-1">Can Video Large Multimodal Models Think Like Doubters-or Double-Down: A Study on Defeasible Video Entailment <a class="header-anchor" href="#can-video-large-multimodal-models-think-like-doubters-or-double-down-a-study-on-defeasible-video-entailment" aria-label="Permalink to &quot;Can Video Large Multimodal Models Think Like Doubters-or Double-Down: A Study on Defeasible Video Entailment&quot;">​</a></h1><table tabindex="0"><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td><strong>arXiv</strong></td><td><a href="https://arxiv.org/abs/2506.22385" target="_blank" rel="noreferrer">2506.22385</a></td></tr><tr><td><strong>提交日期</strong></td><td>2025-06-27（最新版 2025-10-07）</td></tr><tr><td><strong>作者</strong></td><td>Yue Zhang, Jilei Sun, Yunhui Guo, Vibhav Gogate</td></tr><tr><td><strong>分类</strong></td><td>cs.AI, cs.CL, cs.CV</td></tr><tr><td><strong>一句话</strong></td><td>把 VIOLIN 里直接支持/反驳假设的那段证据剪掉造出&quot;中性前提&quot;，再让标注者把被剪掉的语义写成一条文本 update，从而得到判别与生成两个版本的可废止视频蕴涵任务；方法侧则强制模型对同一样本各写一份&quot;这是强化项&quot;和&quot;这是削弱项&quot;的理由，再让一个外部 LLM 结合 ASR 增强的视频描述在两份理由之间做选择与修正。</td></tr></tbody></table><blockquote><p><strong>所属教程</strong>：<a href="/notes/tutorials/long-video-understanding">长视频理解</a></p></blockquote><p>本页依据 <code>arxiv.org/html/2506.22385v1</code> 全文撰写，并用 <code>arxiv.org/e-print/2506.22385</code> 的 TeX 源码（对应最新版）核对；最新版在分类任务里新增了 Qwen2.5-VL 与 InternVL3 两个基座，本页在 §7 里单独标出这部分只见于新版的数字。</p><h2 id="§-1-—-研究问题与重要性" tabindex="-1">§ 1 — 研究问题与重要性 <a class="header-anchor" href="#§-1-—-研究问题与重要性" aria-label="Permalink to &quot;§ 1 — 研究问题与重要性&quot;">​</a></h2><p>视频蕴涵的标准设定是静态的：给一段视频前提和一句假设，判断假设成立与否，判断一旦做出就是终局。作者指出现实推理不是这样运作的——结论很少一成不变，后续出现的信息会强化或削弱最初的推断。他们把这种&quot;推断可被后续信息推翻&quot;的性质叫做 defeasibility，并把它引入视频领域，定义了 DVidE 任务。</p><p>形式化的定义相当干净：给定视频前提 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.2222em;">V</span></span></span></span> 与假设 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0813em;">H</span></span></span></span>，若存在一条与 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.2222em;">V</span></span></span></span> 一致的 update <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.109em;">U</span></span></span></span> 使人类在得知 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.109em;">U</span></span></span></span> 后认为 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0813em;">H</span></span></span></span> 更不可能为真，则称 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0813em;">H</span></span></span></span> 是可废止的，<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.109em;">U</span></span></span></span> 是一个 <strong>weakener</strong>；若人类认为 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0813em;">H</span></span></span></span> 更可能为真，则 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.109em;">U</span></span></span></span> 是 <strong>strengthener</strong>。关键约束是 <strong><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.109em;">U</span></span></span></span> 不得与前提矛盾</strong>——它只能补充，不能推翻已看到的画面。</p><p>这个任务的诊断价值在于它同时考两件难以分开考的能力：<strong>证据整合</strong>（能不能把新信息接进已有推断）与<strong>自信校准</strong>（在应该改口的时候会不会改口）。当前模型的典型行为是&quot;一味坚持&quot;（论文标题里的 double-down），而这个失败模式在只考最终答案的基准上是看不见的。</p><h2 id="§-2-—-前人工作与不足" tabindex="-1">§ 2 — 前人工作与不足 <a class="header-anchor" href="#§-2-—-前人工作与不足" aria-label="Permalink to &quot;§ 2 — 前人工作与不足&quot;">​</a></h2><p><strong>视频理解侧</strong>的既有工作围绕活动识别（UCF101、HMDB）、事件定位（ActivityNet 等）、视频问答展开，共同点是任务目标固定、答案不随附加信息变化。<strong>VIOLIN</strong> 是本文的数据来源：95,322 个（视频前提，文本假设）对，取自 15,887 段视频、共 582 小时，源自热门电视剧与 YouTube 上的电影片段；每段视频的假设被标为 real（视频支持）或 fake（视频反驳）。VIOLIN 提供了视频-语言推理的框架，但它是二元且静态的。</p><p><strong>自然语言推理侧</strong>已经把可废止性做得很成熟。<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord mathnormal" style="margin-right:0.0379em;">δ</span></span></span></span>-NLI 与 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord mathnormal" style="margin-right:0.0379em;">δ</span></span></span></span>-CAUSAL 都带 strengthener / weakener 标注，但它们是纯文本的。SNLI-VE 引入了视觉，但没有可废止性；<strong>DVE</strong> 二者兼有，但<strong>只有单张图像，没有时间推理</strong>。表 2 把这个空位画得很清楚：在&quot;多模态 + 视频 + strengthener + weakener&quot;四栏全打勾的，只有 DVidE。</p><p>缺口因此是结构性的：可废止推理的研究工具全在文本或静态图像上，而&quot;结论随时间推进被修正&quot;这件事最自然的载体恰恰是视频。</p><h2 id="§-3-—-重建作者的思考路径" tabindex="-1">§ 3 — 重建作者的思考路径 <a class="header-anchor" href="#§-3-—-重建作者的思考路径" aria-label="Permalink to &quot;§ 3 — 重建作者的思考路径&quot;">​</a></h2><p>第一步是找一个已经有蕴涵标注的视频数据集。VIOLIN 满足条件，而且它的 real / fake 二分正好对应 strengthener / weakener 两个方向——real 假设需要被强化，fake 假设需要被削弱。</p><p>第二步遇到障碍：VIOLIN 的视频里通常已经含有明确支持或反驳假设的证据，因此前提本身就不中性，可废止推理无从谈起（结论已经定死了，还废止什么）。所以必须先造出<strong>中性前提</strong>。造法是把那段决定性的子片段剪掉。</p><p>第三步是决定 update 从哪来。既然被剪掉的正是决定性证据，那么把它的语义写成文本，就天然是一条与前提一致、且足以改变蕴涵关系的 update。这一步保证了 update 既 grounded 在真实视频内容上，又不与保留下来的前提矛盾。</p><p>第四步转到方法侧。preliminary 实验里 VLMM 表现不佳，作者归因于两点：模型抓不住 update 带来的语义偏移，以及模型听不见对白（而电视剧片段里的关键信息大量藏在台词里）。前者的对策是让模型<strong>同时</strong>写出正反两份理由再选，把单向的直觉判断变成显式的对照；后者的对策是接一个 ASR 引擎把台词补进视频描述。第五步是发现选理由这件事不该让被视觉微调过的 VLMM 自己做（视觉微调常常损伤 LLM 原有的推理能力），所以引入一个外部 LLM 来选；但它看不见画面，于是必须把视频转成文本描述喂给它。</p><h2 id="§-4-—-核心-intuition" tabindex="-1">§ 4 — 核心 Intuition <a class="header-anchor" href="#§-4-—-核心-intuition" aria-label="Permalink to &quot;§ 4 — 核心 Intuition&quot;">​</a></h2><p>模型在可废止推理上失败，多半不是因为它读不懂 update，而是因为它对第一印象过度承诺：一旦形成了&quot;这句话是对的&quot;的直觉，后续信息只会被解读成支持它。对策是<strong>取消单向判断的机会</strong>——强迫模型对同一个 update 分别写出&quot;它为什么强化了假设&quot;和&quot;它为什么削弱了假设&quot;两份理由，再由一个未被视觉微调污染的外部 LLM 结合（ASR 补全过的）视频描述在两份之间裁决。这把一次直觉判断变成了一次对照论证。</p><h2 id="§-5-—-具体方法与完整-pipeline" tabindex="-1">§ 5 — 具体方法与完整 Pipeline <a class="header-anchor" href="#§-5-—-具体方法与完整-pipeline" aria-label="Permalink to &quot;§ 5 — 具体方法与完整 Pipeline&quot;">​</a></h2><p><strong>基准构建。</strong> 从 VIOLIN 随机选取 200 段视频及其标注假设。对每个（视频，假设）对，剪掉直接支持或反驳该假设的子片段：若该片段在视频开头或结尾，保留剩余部分；若在中间，则取两段剩余里<strong>较长的那一段</strong>以保持连贯。剪辑后的片段作为中性前提。随后请标注者<strong>基于被剪掉的子片段</strong>写文本 update——real 假设写 strengthener，fake 假设写 weakener。每个样本经三名独立标注者：第一名写 update，第二名审核并修正，第三名做最终复核。</p><p><strong>统计（表 1）</strong>：测试集共 986 个样本，weakener 与 strengthener 各 493，平均假设长度 17.99 词，平均 update 长度 12.28 词，平均视频时长 16.45 秒，unique 视频 986 个。</p><p><strong>两个子任务</strong>：判别版要求模型 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathcal">M</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">c</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 判定 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.109em;">U</span></span></span></span> 是 strengthener 还是 weakener；生成版要求 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.9694em;vertical-align:-0.2861em;"></span><span class="mord"><span class="mord mathcal">M</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0359em;">g</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span></span></span></span> 根据 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">(</span><span class="mord mathnormal" style="margin-right:0.2222em;">V</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.0813em;">H</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal">G</span><span class="mclose">)</span></span></span></span> 生成一条符合目标 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7224em;vertical-align:-0.0391em;"></span><span class="mord mathnormal">G</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">∈</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">{</span><span class="mord mathnormal" style="margin-right:0.0269em;">w</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal">s</span><span class="mclose">}</span></span></span></span> 的 update。</p><p><strong>Chain of Counterfactual Thought 判别框架（三模块）：</strong></p><ol><li><strong>反事实理由生成</strong>：<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8778em;vertical-align:-0.1944em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0077em;">R</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:-0.0077em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0269em;">w</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0077em;">R</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:-0.0077em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">s</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord"><span class="mord mathrm">VLMM</span></span><span class="mopen">(</span><span class="mord mathnormal" style="margin-right:0.1389em;">P</span><span class="mopen">(</span><span class="mord mathnormal" style="margin-right:0.0813em;">H</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.109em;">U</span><span class="mclose">)</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.2222em;">V</span><span class="mclose">)</span></span></span></span>，即让同一个 VLMM 分别产出&quot;<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.109em;">U</span></span></span></span> 削弱 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0813em;">H</span></span></span></span>&quot;与&quot;<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.109em;">U</span></span></span></span> 强化 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0813em;">H</span></span></span></span>&quot;两份理由。</li><li><strong>ASR 增强的视频内容整合</strong>：先用 VLMM 生成视频描述 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7519em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0278em;">D</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.7519em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">′</span></span></span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord"><span class="mord mathrm">VLMM</span></span><span class="mopen">(</span><span class="mord mathnormal" style="margin-right:0.2222em;">V</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1389em;">P</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.1389em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">d</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mclose">)</span></span></span></span>；再用 ASR 抽出台词 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1389em;">T</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3283em;"><span style="top:-2.55em;margin-left:-0.1389em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">A</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord"><span class="mord mathrm">ASR</span></span><span class="mopen">(</span><span class="mord mathnormal">A</span><span class="mclose">)</span></span></span></span>；最后用 LLM 融合 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0278em;">D</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1.0019em;vertical-align:-0.25em;"></span><span class="mord"><span class="mord mathrm">LLM</span></span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1389em;">P</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3283em;"><span style="top:-2.55em;margin-left:-0.1389em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">A</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1389em;">T</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3283em;"><span style="top:-2.55em;margin-left:-0.1389em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">A</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0278em;">D</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.7519em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">′</span></span></span></span></span></span></span></span></span><span class="mclose">))</span></span></span></span>。ASR 引擎用的是 <strong>Whisper</strong>。</li><li><strong>理由精修与选择</strong>：<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.1389em;">F</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord"><span class="mord mathrm">LLM</span></span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1389em;">P</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3283em;"><span style="top:-2.55em;margin-left:-0.1389em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.1389em;">F</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0077em;">R</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:-0.0077em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">s</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0077em;">R</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:-0.0077em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0269em;">w</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.0278em;">D</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.0813em;">H</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.109em;">U</span><span class="mclose">))</span></span></span></span>，外部 LLM 不仅在两份理由中选一份，还会先修正其中的推理错误再输出最终答案。</li></ol><p><strong>LLM-Guided ASR-Integrated 生成框架</strong>复用模块 2，再用 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.109em;">U</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord"><span class="mord mathrm">LLM</span></span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1389em;">P</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3283em;"><span style="top:-2.55em;margin-left:-0.1389em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.109em;">U</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mopen">(</span><span class="mord mathnormal" style="margin-right:0.0278em;">D</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.0813em;">H</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.1389em;">P</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal">G</span><span class="mclose">))</span></span></span></span> 让 LLM 基于精修描述、前提、假设与目标改写 VLMM 生成的 update。</p><p><strong>一个具体例子</strong>：一段电视剧片段里，男人在门口停顿后转身离开，假设是&quot;他放弃了向女主道歉&quot;。原视频中间那段&quot;他在楼下把花丢进垃圾桶&quot;被剪掉了，因此保留下来的前提对该假设既不支持也不反驳。标注者据被剪片段写出 update&quot;他随后把带来的花扔进了垃圾桶&quot;，这是一条 strengthener。判别时模型被要求同时论证&quot;扔花说明他放弃了&quot;（强化）与&quot;扔花可能只是花蔫了&quot;（削弱），外部 LLM 结合 ASR 补出的台词（例如他在电话里说&quot;算了&quot;）判定前者更成立。</p><h2 id="§-6-—-核心数学推导" tabindex="-1">§ 6 — 核心数学推导 <a class="header-anchor" href="#§-6-—-核心数学推导" aria-label="Permalink to &quot;§ 6 — 核心数学推导&quot;">​</a></h2><p>本文没有需要展开的形式化推导，核心定义与流程已在 §5 给出。仅列出任务的形式化表述以便对照：判别任务是 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.9468em;"></span><span class="mord accent"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.9468em;"><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="mord mathnormal">L</span></span><span style="top:-3.2523em;"><span class="pstrut" style="height:3em;"></span><span class="accent-body" style="left:-0.2222em;"><span class="mord">^</span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord"><span class="mord mathcal">M</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">c</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mopen">(</span><span class="mord mathnormal" style="margin-right:0.2222em;">V</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.0813em;">H</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.109em;">U</span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">∈</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">{</span><span class="mord mathnormal">s</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.0269em;">w</span><span class="mclose">}</span></span></span></span>，其中 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.9468em;"></span><span class="mord accent"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.9468em;"><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="mord mathnormal">L</span></span><span style="top:-3.2523em;"><span class="pstrut" style="height:3em;"></span><span class="accent-body" style="left:-0.2222em;"><span class="mord">^</span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal">s</span></span></span></span> 当且仅当 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.109em;">U</span></span></span></span> 使 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0813em;">H</span></span></span></span> 在给定 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.2222em;">V</span></span></span></span> 下更可能为真；生成任务是 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.9468em;"></span><span class="mord accent"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.9468em;"><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="mord mathnormal" style="margin-right:0.109em;">U</span></span><span style="top:-3.2523em;"><span class="pstrut" style="height:3em;"></span><span class="accent-body" style="left:-0.2222em;"><span class="mord">^</span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1.0361em;vertical-align:-0.2861em;"></span><span class="mord"><span class="mord mathcal">M</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0359em;">g</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mopen">(</span><span class="mord mathnormal" style="margin-right:0.2222em;">V</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.0813em;">H</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal">G</span><span class="mclose">)</span></span></span></span>，<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7224em;vertical-align:-0.0391em;"></span><span class="mord mathnormal">G</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">∈</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">{</span><span class="mord mathnormal" style="margin-right:0.0269em;">w</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal">s</span><span class="mclose">}</span></span></span></span>。约束条件&quot;<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.109em;">U</span></span></span></span> 不得与前提矛盾&quot;没有被形式化，只以标注规范与评测类别 C7（Contradicting the Premise）的形式出现。</p><h2 id="§-7-—-实验设计与结论" tabindex="-1">§ 7 — 实验设计与结论 <a class="header-anchor" href="#§-7-—-实验设计与结论" aria-label="Permalink to &quot;§ 7 — 实验设计与结论&quot;">​</a></h2><p><strong>基座与评测口径。</strong> v1 用了六个 7B 规模的 VLMM：纯视频的 Video-ChatGPT、VideoGPT+、VideoLLaMA_V、VideoLLaMA2_V，以及带音频分支的 VideoLLaMA_AV、VideoLLaMA2_AV。判别任务报 accuracy / precision / recall / F1，外加 <strong>SRatio</strong>（预测为 strengthener 的比例，越接近 50 越好，因为测试集是 493:493 严格平衡的）。生成任务除 ROUGE-L / BLEU-4 / BERTScore 外，还定义了八个类别 C1–C8（C1 Good、C2 Neutral、C3 该强化却削弱、C4 该削弱却强化、C5 复述前提、C6 复述假设、C7 与前提矛盾、C8 无意义），由 <strong>GPT-4o</strong> 依据 VideoLLaMA2 生成的视频描述 + 假设 + 生成的 update 做归类。</p><p><strong>问题一：现有 VLMM 在这个任务上处于什么水平。</strong> 表 3 的基线列（w/Ours = ✗）：VideoLLaMA_V 准确率 52.74 / F1 42.47 / SRatio 32.15；VideoLLaMA_AV 55.07 / 51.69 / 43.00；Video-ChatGPT 61.05 / 45.61 / 21.60；VideoGPT+ 72.76 / 70.02 / 40.71；VideoLLaMA2_V 59.84 / 65.98 / 68.05；VideoLLaMA2_AV 52.94 / 67.60 / <strong>95.23</strong>。最后一行值得单独看：SRatio 95.23 意味着该模型把 95% 的样本都判成 strengthener，recall 98.17 是这种退化行为的直接产物，而准确率 52.94 几乎就是<strong>随机水平</strong>（平衡二分类的随机基线是 50）。这是&quot;一味坚持&quot;最赤裸的量化证据。</p><p><strong>问题二：ASR 有没有用。</strong> 同一表内比较视频-音频模型与其纯视频版本：VideoLLaMA 的 F1 从 42.47 升到 51.69，VideoLLaMA2 从 65.98 升到 67.60。作者据此说加入音频能提升性能。</p><p><strong>问题三：本文框架的增益。</strong> 加上框架后（w/Ours = ✓）：VideoLLaMA_V 76.55 / 74.97 / 43.71；VideoLLaMA_AV 77.48 / 75.39 / 41.48；Video-ChatGPT 77.79 / 75.31 / 39.95；VideoGPT+ 77.16 / 77.74 / 43.65；VideoLLaMA2_V 77.89 / 76.20 / 43.40；VideoLLaMA2_AV 78.80 / 77.31 / 42.90。两个现象很清楚：其一，<strong>所有基座被拉到 76.5–78.8 的窄区间内</strong>，基座之间原本 20 个点的差距被抹平；其二，SRatio 全部收敛到 40–44，预测分布明显变均衡。</p><p><strong>只见于最新版的数字</strong>：v2 新增两个更强的基座。Qwen2.5-VL 基线 71.10 / F1 70.30 / SRatio 36.71，加框架后 77.18 / 77.01 / 36.21；InternVL3 基线 74.65 / F1 74.14 / SRatio 44.52，加框架后 76.67 / 76.53 / 33.57。<strong>基座越强，框架的增益越小</strong>（InternVL3 只有 +2.0 准确率），且 InternVL3 的 SRatio 反而从 44.52 恶化到 33.57。</p><p><strong>问题四：生成任务。</strong> 表 4 的 C1（Good）比例：Video-ChatGPT 39.29 → 64.86，VideoGPT+ 35.74 → 52.78，VideoLLaMA_V 7.50 → 60.63，VideoLLaMA_AV 13.96 → 63.20，VideoLLaMA2_V 48.68 → 56.99，VideoLLaMA2_AV 47.04 → 58.76。C8（无意义）显著下降，例如 VideoLLaMA_V 从 34.41 降到 0.86。但同时 <strong>C4（该削弱却强化）普遍上升</strong>：VideoGPT+ 从 23.68 升到 29.24，VideoLLaMA2_V 从 14.77 升到 29.33，VideoLLaMA2_AV 从 14.41 升到 28.71。也就是说框架在减少&quot;废话式 update&quot;的同时，把一部分错误转移成了&quot;方向反了&quot;。作者在正文里只强调了 C3 的下降，没有讨论 C4 的上升。</p><p><strong>问题五：各模块贡献。</strong> 表 5 以准确率 / 精确率 / 召回率 / F1 报告。VideoLLaMA2_AV + Ours 是 78.80 / 83.18 / 72.21 / 77.31；去掉精修描述降到 77.69 / 87.19 / 64.91 / 74.42；去掉反事实降到 70.79 / 93.25 / <strong>44.83</strong> / 60.55。VideoLLaMA2_V + Ours 是 77.89 / 82.51 / 70.79 / 76.20；去掉精修描述 76.37 / 85.52 / 63.49 / 72.88；去掉反事实 71.60 / 88.45 / <strong>49.70</strong> / 63.64。<strong>反事实模块是主力</strong>，去掉它 recall 会腰斩、precision 反而飙到 88–93，这是典型的&quot;退回单向偏置&quot;——模型又开始只在极有把握时才判 strengthener。</p><p><strong>问题六：自动评测靠不靠谱。</strong> 附录 A 做了人工评测：从 VideoGPT+ 与 VideoLLaMA2 各取原始与精修版本共 400 个样本（每模型 100 个实例），每条由三名评估者按同样八类归类，取多数票。结果 VideoGPT+ 的 C1 从 <strong>21% 升到 88%</strong>，VideoLLaMA2 从 <strong>50% 升到 84%</strong>。</p><h2 id="§-8-—-take-aways" tabindex="-1">§ 8 — Take-aways <a class="header-anchor" href="#§-8-—-take-aways" aria-label="Permalink to &quot;§ 8 — Take-aways&quot;">​</a></h2><p><strong>5 句版</strong>：把&quot;给出新信息后能否修正结论&quot;做成任务，需要先造出中性前提，而 Grounded 视频数据集里被标注的决定性证据段恰好可以被剪掉来实现这件事，被剪掉的语义则天然构成一条与前提一致的 update。可废止判别的失败模式在平衡二分类下是可见的：VideoLLaMA2_AV 把 95% 的样本判成 strengthener，准确率 52.94 约等于随机，这就是&quot;double-down&quot;的量化形态。强制模型对同一 update 同时写出正反两份理由，再交给一个未被视觉微调的外部 LLM 裁决，把六个基座全部拉到 76.5–78.8 且 SRatio 收敛到 40–44。消融显示反事实模块是主力（去掉它 recall 从 70–72 掉到 45–50），ASR 增强次之。但在更强的基座上增益迅速衰减（InternVL3 只 +2.0），且 GPT-4o 判定的 C1 与人工判定的 C1 差距很大（VideoGPT+ 精修后：自动 52.78 vs 人工 88），自动指标与人工标注之间没有报告一致率。</p><p><strong>3 句版</strong>：DVidE 用&quot;剪掉证据段 + 把被剪语义写成文本 update&quot;的方式，把可废止推理引入视频域，测试集 986 条、strengthener/weakener 严格 493:493。方法上用强制的正反双理由 + 外部 LLM 裁决压住模型的单向偏置，SRatio 从最差的 95.23 收敛到 42.90。增益在弱基座上很大、在强基座上很小，且生成任务的 C4（方向判反）在加了框架后普遍上升。</p><p><strong>1 句版</strong>：可废止推理基准必须报预测分布（本文的 SRatio），否则一个把所有样本判成同一类的模型也能在 F1 上看起来不差。</p><h2 id="§-9-—-最脆弱的假设" tabindex="-1">§ 9 — 最脆弱的假设 <a class="header-anchor" href="#§-9-—-最脆弱的假设" aria-label="Permalink to &quot;§ 9 — 最脆弱的假设&quot;">​</a></h2><p>最脆弱的一条是：<strong>判别 strengthener 与 weakener 需要看视频</strong>。整个 DVidE 判别任务的合法性建立在这个前提上；如果不需要，那么它就是一个伪装成视频任务的纯文本 NLI 任务，表 3 的所有比较都在测别的东西。</p><p>这条假设很可能不成立，理由来自本文自己的数据构造。update 是标注者<strong>基于被剪掉的子片段</strong>写的，其内容对应的正是&quot;直接支持或反驳假设&quot;的那段证据。因此 update 与假设之间存在<strong>直接的文本蕴涵关系</strong>——strengthener 在语义上支持假设，weakener 在语义上与假设冲突。一个纯文本的 NLI 模型只看 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">(</span><span class="mord mathnormal" style="margin-right:0.0813em;">H</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.109em;">U</span><span class="mclose">)</span></span></span></span> 就能判断这个方向，根本不需要 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.2222em;">V</span></span></span></span>。作者自己在 §4.2 里写道&quot;文本信息作为被移除子片段语义的替代，为蕴涵关系推断提供直接证据&quot;——这句话等于承认了 update 单独就携带判别所需的全部信息。</p><p>论文为这条假设提供的证据，我在可见正文与附录中没有找到。<strong>没有报告任何 video-blind 基线</strong>：既没有&quot;只给 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0813em;">H</span></span></span></span> 和 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.109em;">U</span></span></span></span>、不给视频&quot;的纯文本 LLM 分数，也没有&quot;给随机视频 + 正确 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8778em;vertical-align:-0.1944em;"></span><span class="mord mathnormal" style="margin-right:0.0813em;">H</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.109em;">U</span></span></span></span>&quot;的对照。这是一处彻底的缺失证据，而且它恰好落在本领域最常见的陷阱上。间接的迹象反而不利：本文框架的最后一步 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.1389em;">F</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord"><span class="mord mathrm">LLM</span></span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1389em;">P</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3283em;"><span style="top:-2.55em;margin-left:-0.1389em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.1389em;">F</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0077em;">R</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:-0.0077em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">s</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0077em;">R</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:-0.0077em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0269em;">w</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.0278em;">D</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.0813em;">H</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.109em;">U</span><span class="mclose">))</span></span></span></span> 由一个<strong>看不见画面</strong>的 LLM 做决策，它拿到的视觉信息只是一段文本描述 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0278em;">D</span></span></span></span>；而消融表 5 显示去掉这段描述（w/o-Refined description）准确率只从 78.80 掉到 77.69、从 77.89 掉到 76.37——<strong>视觉信息整体只值 1.1–1.5 个点</strong>。</p><h2 id="§-10-—-最小复现实验" tabindex="-1">§ 10 — 最小复现实验 <a class="header-anchor" href="#§-10-—-最小复现实验" aria-label="Permalink to &quot;§ 10 — 最小复现实验&quot;">​</a></h2><p>一周内可做完，目标是把&quot;视频到底值多少&quot;量化出来。全部实验都在公开的 986 条测试集上。</p><ol><li><strong>纯文本盲测</strong>：把 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">(</span><span class="mord mathnormal" style="margin-right:0.0813em;">H</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.109em;">U</span><span class="mclose">)</span></span></span></span> 喂给一个不看视频的文本 LLM（例如任一 7B 开源模型），要求判 strengthener / weakener，报准确率与 SRatio。若分数接近甚至超过表 3 里最好的 78.80，则判别任务的视觉必要性被否定。</li><li><strong>随机视频对照</strong>：保持 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">(</span><span class="mord mathnormal" style="margin-right:0.0813em;">H</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.109em;">U</span><span class="mclose">)</span></span></span></span> 不变，把视频前提替换成从测试集中随机抽取的另一段无关视频，跑完整框架。若准确率下降幅度小于 2 个点（即与表 5 里去掉描述的幅度相当），则说明视觉通路承载的信息本来就微弱。</li><li><strong>update 遮蔽对照</strong>：保持视频不变，把 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.109em;">U</span></span></span></span> 的内容打乱或替换成同类型的随机 update，跑完整框架。这条与第 1 条互补，用来确认信息确实集中在 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.109em;">U</span></span></span></span> 上。</li><li><strong>判据</strong>：把三条结果并排看。理想情况是 1 显著低于完整框架、2 显著低于完整框架；若 1 很高而 2 几乎不掉，则 DVidE 判别版应当被重新定位成一个&quot;以视频为背景的文本可废止推理&quot;基准，而不是视频推理基准。这个结论不会否定数据集的价值，但会改变它该被怎么用。</li><li>生成任务另做一条：把 GPT-4o 的八类归类结果与附录 A 的 400 条人工标注<strong>逐条对齐</strong>，算 Cohen&#39;s kappa 与混淆矩阵。论文只并列展示了两组比例，没有报告一致率。</li></ol><h2 id="§-11-—-最强反例设计" tabindex="-1">§ 11 — 最强反例设计 <a class="header-anchor" href="#§-11-—-最强反例设计" aria-label="Permalink to &quot;§ 11 — 最强反例设计&quot;">​</a></h2><p>最强的攻击是构造<strong>纯文本捷径基线</strong>，即 §10 的第 1 条。这里给出它为什么大概率会成功的具体论证：update 平均只有 12.28 词，假设平均 17.99 词，两者都是标注者围绕同一段被剪证据写出来的短句；strengthener 与 hypothesis 在词汇与命题上高度重合，weakener 则包含否定、对立动词或不相容状态。这正是 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord mathnormal" style="margin-right:0.0379em;">δ</span></span></span></span>-NLI 这类纯文本可废止数据集所刻画的模式，而那些数据集上的 SOTA 早已远超 80%。如果一个 3B 的文本模型就能在 DVidE 上拿到 80+，那么表 3 里六个 VLMM 从 52.7 到 72.8 的差异，测的其实是它们<strong>作为语言模型</strong>的能力，而不是它们看视频的能力。</p><p>第二重攻击针对<strong>自动评测与人工评测的分歧</strong>。生成任务的头条是表 4 的 C1，由 GPT-4o 判定。把它与附录 A 的人工结果对照：VideoGPT+ 原始版 GPT-4o 给 35.74、人工给 21；精修版 GPT-4o 给 52.78、人工给 <strong>88</strong>。VideoLLaMA2_V 原始版 GPT-4o 给 48.68、人工给 50；精修版 GPT-4o 给 56.99、人工给 84。两组数据的样本量不同（全量 986 vs 抽样 100），因此不构成严格的逐条比较，但<strong>方向与幅度的差异太大</strong>：人工认为精修版有 84–88% 的 update 是好的，GPT-4o 只认 53–57%。按本教程的红线，一个用来给模型打分的自动 checker 必须先对齐真值再使用，而本文只是把两组数并列展示，没有给一致率、没有给 kappa、也没有讨论分歧原因。构造反例的方式很直接：在同一批 400 条上同时报 GPT-4o 与人工的逐条标签，算混淆矩阵。若 GPT-4o 系统性地把人工判为 C1 的样本判成 C4（&quot;该削弱却强化&quot;），那么表 4 里 C4 普遍上升这个现象就是评测器的伪影，而不是模型的退化。</p><p>第三重是两处<strong>正文与表格不一致</strong>，它们会误导只读正文的读者：</p><ul><li>§4.2 写&quot;随机选取 <strong>200</strong> 段 VIOLIN 视频&quot;，而表 1 写 unique 视频 <strong>986</strong> 段、总样本 986 条。两个数字在 v1 与最新版里都并存，无法同时为真。若实际只有 200 段源视频而样本有 986 条，则平均每段视频贡献约 5 条样本，样本之间<strong>不独立</strong>，所有指标的有效样本量远小于 986，置信区间应据此放宽——而论文全篇没有报告任何置信区间。</li><li>§7.3 写&quot;VideoLLaMA2_AV 的 recall 从 72.21%（w/ ours）掉到 44.83%（w/o refined description）&quot;，但表 5 里 w/o-Refined description 那一行的 recall 是 <strong>64.91</strong>，44.83 属于 w/o-Counterfactual 那一行。同一段还写&quot;VideoLLaMA2_V 的 recall 从 77.89% 掉到 49.70%&quot;，而 77.89 是<strong>准确率</strong>、其 recall 是 70.79。正文把两个消融项的效果张冠李戴，且这两句话正是用来论证 ASR 模块重要性的——按表格，ASR 模块的真实效果比正文声称的小得多。</li></ul><h2 id="§-12-—-follow-up-research-idea" tabindex="-1">§ 12 — Follow-up Research Idea <a class="header-anchor" href="#§-12-—-follow-up-research-idea" aria-label="Permalink to &quot;§ 12 — Follow-up Research Idea&quot;">​</a></h2><p><strong>驱动局限</strong>：DVidE 目前把 update 做成<strong>外生的文本</strong>——它由标注者写好，从模型外部塞进来。这个设计使任务可控，但也把最有意思的那一半切掉了：真实的可废止推理里，新证据是<strong>在视频里继续出现的</strong>，而不是有人写成一句话递给你。正因为 update 是文本，纯文本捷径才有可乘之机（§9），视觉通路才只值 1 个多点（表 5）。</p><p><strong>新 framing</strong>：把 update 从文本还原成<strong>视频的后续片段</strong>，任务变成&quot;给定前 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6151em;"></span><span class="mord mathnormal">t</span></span></span></span> 秒与一个假设，模型给出一个置信度；随着视频继续播放到 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6984em;vertical-align:-0.0833em;"></span><span class="mord mathnormal">t</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord">Δ</span></span></span></span>，模型必须更新这个置信度&quot;。评测的对象不再是二分类标签，而是<strong>置信度轨迹的形状</strong>：在关键证据出现的那一帧，置信度应该发生显著跳变；在无关内容上应该保持平稳。这直接把 §1 提到的&quot;证据整合 + 自信校准&quot;两件事变成了可测量的量，而且纯文本模型完全无法参与——因为没有文本 update 可读。本文的数据构造恰好为此准备好了原料：<strong>被剪掉的子片段就是那个应该引发跳变的证据</strong>，它的精确时间位置是已知的。可借鉴的工具来自序贯决策与在线校准（Brier score 的时间分解、prequential 评估），以及流式视频理解里按时间戳提问的评测协议。</p><p><strong>第一个实验</strong>：不需要新标注。取本文的 986 个样本，把被剪掉的子片段<strong>放回原位</strong>，得到完整视频与已知的证据时间戳 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7651em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal">t</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">e</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span>。让模型每隔 2 秒输出一次对假设的置信度 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal">p</span><span class="mopen">(</span><span class="mord mathnormal" style="margin-right:0.0813em;">H</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">∣</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.2222em;">V</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2952em;"><span style="top:-2.55em;margin-left:-0.2222em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mrel mtight">≤</span><span class="mord mathnormal mtight">t</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2452em;"><span></span></span></span></span></span></span><span class="mclose">)</span></span></span></span>，画出轨迹。测两个量：一是 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7651em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal">t</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">e</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 前后的置信度跳变幅度 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord">∣</span><span class="mord mathnormal">p</span><span class="mopen">(</span><span class="mord mathnormal" style="margin-right:0.0813em;">H</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">∣</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1.0001em;vertical-align:-0.2501em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.2222em;">V</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.2222em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mrel mtight">≤</span><span class="mord mtight"><span class="mord mathnormal mtight">t</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1645em;"><span style="top:-2.357em;margin-left:0em;margin-right:0.0714em;"><span class="pstrut" style="height:2.5em;"></span><span class="sizing reset-size3 size1 mtight"><span class="mord mathnormal mtight">e</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.143em;"><span></span></span></span></span></span></span><span class="mbin mtight">+</span><span class="mord mathnormal mtight" style="margin-right:0.0379em;">δ</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2501em;"><span></span></span></span></span></span></span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal">p</span><span class="mopen">(</span><span class="mord mathnormal" style="margin-right:0.0813em;">H</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">∣</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1.0001em;vertical-align:-0.2501em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.2222em;">V</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.2222em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mrel mtight">≤</span><span class="mord mtight"><span class="mord mathnormal mtight">t</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1645em;"><span style="top:-2.357em;margin-left:0em;margin-right:0.0714em;"><span class="pstrut" style="height:2.5em;"></span><span class="sizing reset-size3 size1 mtight"><span class="mord mathnormal mtight">e</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.143em;"><span></span></span></span></span></span></span><span class="mbin mtight">−</span><span class="mord mathnormal mtight" style="margin-right:0.0379em;">δ</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2501em;"><span></span></span></span></span></span></span><span class="mclose">)</span><span class="mord">∣</span></span></span></span>，二是非证据区间上的轨迹方差（衡量无谓抖动）。先在 VideoLLaMA2_AV、Qwen2.5-VL、InternVL3 上各跑一遍。预期发现是：模型的置信度轨迹在证据帧上几乎不跳，抖动却主要来自镜头切换——若这个预期被证实，就说明当前 VLMM 的&quot;改口&quot;能力不是被文本 update 的措辞卡住的，而是根本没有把视觉证据接入置信度更新，那么整条研究线的重心应从&quot;怎么写好 update&quot;转到&quot;怎么让置信度对视觉事件敏感&quot;。这个实验一周内可完成，且它给出的诊断是当前 DVidE 判别版结构上给不出的。</p>',58)])])}const d=a(e,[["render",l]]);export{g as __pageData,d as default};
